local mobiled_platform_capabilities_ = {
    objectType = {
        name = 'rpc.mobiled.platform.capabilities.',
        access = 'readOnly',
        minEntries = 1,
        maxEntries = 1,
        parameters = {
            module_power_control = {
                access = "readOnly",
                type = "boolean"
            },
            antenna_selection = {
                access = "readOnly",
                type = "boolean"
            }
        }
    }
}

local conn = mapper("ubus").connect()
if not conn then
    return
end

local helper = require("mobiled.scripthelpers")

local function getall(mapping, key)
    return helper.getUbusData(conn, "mobiled.platform", "capabilities", {})
end

local function get(mapping, paramName, key)
    return getall(mapping, key)[paramName]
end

mobiled_platform_capabilities_.getall = getall
mobiled_platform_capabilities_.get = get

register(mobiled_platform_capabilities_)
